interface CartElement extends HTMLElement {
  changeItemQuantity: (itemId: string | number, quantity: number) => void;
}

class LineItemEl extends HTMLElement {
  private toggleButton: HTMLElement | null = null;
  private components: HTMLElement | null = null;
  private removeButton: HTMLElement | null = null;

  connectedCallback() {
    this.cacheDomElements();
    this.setupEventListeners();
  }

  disconnectedCallback() {
    this.teardownEventListeners();
  }

  private cacheDomElements(): void {
    this.toggleButton = this.querySelector('[js-line-item="toggle"]');
    this.components = this.querySelector('[js-line-item="components"]');
    this.removeButton = this.querySelector('[js-line-item="remove"]');
  }

  private setupEventListeners(): void {
    this.toggleButton?.addEventListener("click", this.handleToggleEvent);
    this.removeButton?.addEventListener("click", this.handleRemoveEvent);
  }

  private teardownEventListeners(): void {
    this.toggleButton?.removeEventListener("click", this.handleToggleEvent);
    this.removeButton?.removeEventListener("click", this.handleRemoveEvent);
  }

  private handleToggleEvent = () => {
    if (!this.components || !this.toggleButton) return;

    this.components.classList.toggle("is-hidden");
    this.toggleButton.classList.toggle("is-active");

    const showText = this.toggleButton.getAttribute("data-show-text");
    const hideText = this.toggleButton.getAttribute("data-hide-text");
    const span = this.toggleButton.querySelector("span");

    if (this.components.classList.contains("is-hidden")) {
      if (span && showText) span.textContent = showText;
      this.style.setProperty("--line-item-components-height", "0px");
    } else {
      if (span && hideText) span.textContent = hideText;
      this.style.setProperty("--line-item-components-height", "auto");
      const height = this.components.scrollHeight - 20;
      this.style.setProperty("--line-item-components-height", `${height}px`);
    }
  };

  private handleRemoveEvent = (evt: Event) => {
    evt.preventDefault();

    const lineStr = this.getAttribute("data-line");
    const line = lineStr ? parseInt(lineStr, 10) : NaN;
    const cart = document.querySelector<CartElement>("uwp-cart");

    if (!line || Number.isNaN(line)) {
      const key = this.getAttribute("data-key");
      if (key) {
        cart?.changeItemQuantity(key, 0);
        return;
      }
      console.warn("LineItem: No valid line or key found");
      return;
    }

    cart?.changeItemQuantity(line, 0);
  };
}

customElements.define("line-item", LineItemEl);
